"""Read configurable local Markdown/CSV evidence without classifying payroll."""

from __future__ import annotations

import argparse
from collections import Counter
from dataclasses import dataclass
from decimal import Decimal
import csv
import io
import json
import os
from pathlib import Path
import re
import sys
from typing import Iterable


# These are column names, not employer names or classification rules.
DEFAULT_MONEY_COLUMNS = frozenset({
    "wages_paid", "gross_pay", "travel_allowance_paid", "amount_paid",
    "dine_in_receipts", "offsite_catering_receipts",
})
_MONEY = re.compile(r"[+-]?[0-9]+(?:\.[0-9]{1,2})?")
_PARAGRAPH = re.compile(r"(?m)^[ \t]*(?:#{1,6}[ \t]+)?(?:\*\*)?(CG-[0-9]+)\.")


class InputError(ValueError):
    """A source cannot be read or does not meet the documented input format."""


@dataclass(frozen=True)
class MarkdownSource:
    path: Path
    text: str
    paragraph_ids: tuple[str, ...]


@dataclass(frozen=True)
class CSVRow:
    line_number: int
    values: dict[str, str | Decimal]


@dataclass(frozen=True)
class CSVSource:
    path: Path
    text: str
    columns: tuple[str, ...]
    rows: tuple[CSVRow, ...]


@dataclass(frozen=True)
class Inputs:
    guide: MarkdownSource
    records_root: Path
    records: tuple[MarkdownSource | CSVSource, ...]


def _read_text(path: Path) -> str:
    try:
        # Preserve line endings and any BOM in source text for later citation.
        with path.open(encoding="utf-8", newline="") as source:
            return source.read()
    except UnicodeError as exc:
        raise InputError(f"{path}: expected UTF-8 text: {exc}") from exc
    except OSError as exc:
        raise InputError(f"{path}: cannot read source: {exc.strerror or exc}") from exc


def read_markdown(path: str | Path) -> MarkdownSource:
    """Preserve Markdown text and paragraph-definition identifiers in source order."""
    path = Path(path)
    text = _read_text(path)
    identifiers = tuple(_PARAGRAPH.findall(text.removeprefix("\ufeff")))
    return MarkdownSource(path, text, identifiers)


def _csv_lines(text: str, path: Path) -> Iterable[str]:
    """Check quote placement that csv.reader(strict=True) otherwise accepts."""
    state = "start"
    for line_number, line in enumerate(io.StringIO(text.removeprefix("\ufeff"), newline=""), 1):
        for character in line:
            if state == "quoted":
                if character == '"':
                    state = "closed"
            elif state == "closed":
                if character == '"':  # Doubled quote within a quoted field.
                    state = "quoted"
                elif character in ",\r\n":
                    state = "start"
                else:
                    raise InputError(f"{path}:{line_number}: malformed CSV: character after closing quote")
            elif character == '"':
                if state != "start":
                    raise InputError(f"{path}:{line_number}: malformed CSV: quote inside unquoted field")
                state = "quoted"
            elif character in ",\r\n":
                state = "start"
            else:
                state = "bare"
        yield line


def read_csv(
    path: str | Path, *, money_columns: Iterable[str] = DEFAULT_MONEY_COLUMNS,
) -> CSVSource:
    """Read a strict CSV table, converting configured money columns to Decimal."""
    path = Path(path)
    text = _read_text(path)
    money_columns = frozenset(money_columns)
    parser = csv.reader(_csv_lines(text, path), strict=True)
    rows = []
    try:
        header = next(parser, None)
        if not header:
            raise InputError(f"{path}:1: CSV header is missing")
        if any(not name or name != name.strip() for name in header):
            raise InputError(f"{path}:1: CSV headers must be nonblank without surrounding whitespace")
        if len(set(header)) != len(header):
            raise InputError(f"{path}:1: duplicate CSV header")
        while True:
            line_number = parser.line_num + 1
            row = next(parser, None)
            if row is None:
                break
            if not row:  # Blank physical lines do not create evidence rows.
                continue
            if len(row) != len(header):
                raise InputError(f"{path}:{line_number}: expected {len(header)} fields, got {len(row)}")
            values: dict[str, str | Decimal] = dict(zip(header, row))
            for column, value in zip(header, row):
                if column in money_columns:
                    if not _MONEY.fullmatch(value.strip()):
                        raise InputError(
                            f"{path}:{line_number}: invalid money in column {column!r}: {value!r}; "
                            "expected plain decimal dollars with at most two fractional digits"
                        )
                    values[column] = Decimal(value.strip())
            rows.append(CSVRow(line_number, values))
    except csv.Error as exc:
        raise InputError(f"{path}:{parser.line_num}: malformed CSV: {exc}") from exc
    return CSVSource(path, text, tuple(header), tuple(rows))


def read_inputs(
    guide_path: str | Path,
    employer_records_path: str | Path,
    *,
    money_columns: Iterable[str] = DEFAULT_MONEY_COLUMNS,
) -> Inputs:
    """Reread a guide and all Markdown/CSV records below a caller-supplied directory.

    The directory can hold one employer or any number of employer subdirectories.
    No employer names, minimum employer count, or classification answers are assumed.
    """
    guide = read_markdown(guide_path)
    if not guide.paragraph_ids:
        raise InputError(f"{guide.path}: no classification paragraph identifiers (CG-...) found")
    root = Path(employer_records_path)
    try:
        is_directory = root.is_dir()
    except OSError as exc:
        raise InputError(f"{root}: cannot access employer records directory: {exc.strerror or exc}") from exc
    if not is_directory:
        raise InputError(f"{root}: employer records directory is missing or is not a directory")

    def walk_error(exc: OSError) -> None:
        raise InputError(f"{exc.filename}: cannot list employer records: {exc.strerror}") from exc

    paths = sorted(
        Path(directory) / name
        for directory, _, names in os.walk(root, onerror=walk_error)
        for name in names
        if Path(name).suffix.lower() in {".md", ".csv"}
    )
    if not paths:
        raise InputError(f"{root}: no Markdown or CSV employer records found")
    money_columns = frozenset(money_columns)
    records = tuple(
        read_csv(path, money_columns=money_columns)
        if path.suffix.lower() == ".csv" else read_markdown(path)
        for path in paths
    )
    return Inputs(guide, root, records)


def inventory(inputs: Inputs) -> dict:
    """Summarize the input inventory without calculating payroll totals or allocations."""
    tables = [doc for doc in inputs.records if isinstance(doc, CSVSource)]
    return {
        "guide": {"path": str(inputs.guide.path), "paragraph_ids": inputs.guide.paragraph_ids},
        "records_root": str(inputs.records_root),
        "record_files": len(inputs.records),
        "markdown_files": len(inputs.records) - len(tables),
        "csv_files": len(tables),
        "csv_rows": sum(len(table.rows) for table in tables),
        "decimal_values": sum(
            isinstance(value, Decimal)
            for table in tables for row in table.rows for value in row.values.values()
        ),
        "records_by_directory": dict(sorted(Counter(
            doc.path.parent.relative_to(inputs.records_root).as_posix()
            for doc in inputs.records
        ).items())),
        "sources": [doc.path.relative_to(inputs.records_root).as_posix() for doc in inputs.records],
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--guide", required=True, type=Path, help="Classification Guide Markdown path")
    parser.add_argument("--employers", required=True, type=Path, help="Directory of employer Markdown/CSV records")
    parser.add_argument("--money-column", action="append", default=[], help="Additional CSV money column; repeat as needed")
    args = parser.parse_args(argv)
    try:
        inputs = read_inputs(
            args.guide, args.employers,
            money_columns=DEFAULT_MONEY_COLUMNS.union(args.money_column),
        )

    def evaluate_batch(
        self, subcontractors: Iterable[SubcontractorCase] = (), travel: Iterable[TravelCase] = (),
    ) -> AdjustmentResult:
        subcontractors, travel = tuple(subcontractors), tuple(travel)
        lines = tuple(self.subcontractor(case) for case in subcontractors) + tuple(self.travel(case) for case in travel)
        return summarize_adjustments(lines, expected_cases=(*subcontractors, *travel))


def _controls(entries):
    controls = {}
    seen_sources = set()
    workers = []
    for kind, period, record in entries:
        if kind == "subcontractor" and isinstance(record, SubcontractorPayment):
            record_id = record.payment_id
        elif kind == "travel" and isinstance(record, TravelAllowance):
            record_id = record.allowance_id
            _id(record.employee_id, "Worker")
        else:
            raise AdjustmentError("Adjustment kind does not match its original input record")
        key = kind, _id(record_id, "Adjustment record")
        try:
            source_key = _source_key(record.source)
        except AllocationError as exc:
            raise AdjustmentError(str(exc)) from exc
        if key in controls:
            raise AdjustmentError(f"{key}: duplicate adjustment ID or original monetary source row")
        if kind == "travel":
            for employee, prior_period in workers:
                same_worker = employee == record.employee_id
                overlap = _valid_period(period) and _valid_period(prior_period) and period.start <= prior_period.end and prior_period.start <= period.end
                if same_worker and (overlap or period == prior_period):
                    raise AdjustmentError(f"{employee}: duplicate/overlapping worker-period allowance total; the daily cap cannot be applied twice")
            workers.append((record.employee_id, period))
        monetary_sources = {source_key}
        if kind == "travel":
            monetary_sources.update(_source_key(day.source) for day in (record.daily_payments or ()) if _has_source(day.source))
        if monetary_sources.intersection(seen_sources):
            raise AdjustmentError(f"{key}: duplicate original monetary source row across adjustment cases")
        seen_sources.update(monetary_sources)
        _amount(record.amount, str(key))
        controls[key] = period, record
    return controls


def reconcile_adjustments(
    lines: Iterable[AdjustmentLine], *,
    expected_cases: Iterable[SubcontractorCase | TravelCase] | None = None,
) -> AdjustmentReconciliation:
    """Reconcile against independent input cases when supplied; ignore proposals."""
    lines = tuple(lines)
    if expected_cases is None:
        entries = ((line.kind, line.period, line.input_record) for line in lines)
    else:
        entries = []
        for case in expected_cases:
            if isinstance(case, SubcontractorCase):
                entries.append(("subcontractor", case.period, case.payment))
            elif isinstance(case, TravelCase):
                entries.append(("travel", case.period, case.allowance))
            else:
                raise AdjustmentError("Expected a subcontractor or travel input case for reconciliation")
    controls = _controls(entries)
    basis_total = sum(_amount(record.amount, str(key)) for key, (_, record) in controls.items())
    payroll = nonpayroll = unresolved = 0
    differences = {}
    for line in lines:
        key = line.kind, line.adjustment_id
        if key in differences:
            raise AdjustmentError(f"{key}: duplicate adjustment output")
        if key not in controls or controls[key] != (line.period, line.input_record):
            raise AdjustmentError(f"{key}: output does not match an original input case")
        basis = _amount(controls[key][1].amount, str(key))
        added = _amount(line.payroll_added, str(key))
        excluded = _amount(line.nonpayroll, str(key))
        pending = _amount(line.unresolved_basis, str(key))
        if line.status == "OPEN":
            if added or excluded or line.class_code is not None or line.rationale_ref is not None or not line.required_confirmation:
                raise AdjustmentError(f"{key}: OPEN records cannot contribute verified amounts or codes")
        elif line.status == "VERIFIED":
            if pending or line.proposal is not None or line.required_confirmation or added < 0 or excluded < 0:
                raise AdjustmentError(f"{key}: inconsistent verified adjustment fields")
            if added > 0:
                part = PayrollPart(line.adjustment_id, "adjustment", _money(added), line.input_record.source)
                issue = _decision_issue(line.input_record.decision, part)
                if issue or line.class_code != line.input_record.decision.class_code or line.rationale_ref != line.input_record.decision.rationale_ref:
                    raise AdjustmentError(f"{key}: unverified classification on a claimed payroll addition")
            elif line.class_code is not None or line.rationale_ref is not None:
                raise AdjustmentError(f"{key}: zero payroll addition cannot carry a classification")
        else:
            raise AdjustmentError(f"{key}: unknown adjustment status")
        differences[key] = _money(basis - added - excluded - pending)
        payroll += added
        nonpayroll += excluded
        unresolved += pending
    missing = tuple(key for key in controls if key not in differences)
    differences.update((key, _money(_amount(controls[key][1].amount, str(key)))) for key in missing)
    return AdjustmentReconciliation(_money(basis_total), _money(payroll), _money(nonpayroll), _money(unresolved), _money(basis_total - payroll - nonpayroll - unresolved), differences, missing)


def summarize_adjustments(
    lines: Iterable[AdjustmentLine], *,
    expected_cases: Iterable[SubcontractorCase | TravelCase] | None = None,
) -> AdjustmentResult:
    lines = tuple(lines)
    check = reconcile_adjustments(lines, expected_cases=expected_cases)
    if not check.reconciled:
        raise AdjustmentError("Adjustment amounts do not reconcile to their original monetary records")
    by_code = {}
    for line in lines:
        if line.status == "VERIFIED" and line.class_code is not None:
            by_code[line.class_code] = by_code.get(line.class_code, 0) + _amount(line.payroll_added, line.adjustment_id)
    return AdjustmentResult(lines, {code: _money(cents) for code, cents in sorted(by_code.items()) if cents}, check)

